style.css:
@-moz-document domain("pinterest.com") {
html, body {
    height: 100%;
    margin: 0;
    background-color: #0d0d0d !important; /* negro más suave, no tan fuerte */
    color: #f2e2c4 !important; /* tono dorado-beige elegante */
    scroll-behavior: smooth;
  }

  /* Fondo fijo de piel de leopardo */
  body::before {
    content: "";
    position: fixed;
    top: 40px;
    bottom: 40px;
    left: 40px;
    right: 40px;
    background-image: url("https://static4.depositphotos.com/1019221/338/i/450/depositphotos_3382879-stock-illustration-leopard-background.jpg");
    background-size: cover;
    background-position: center;
    border-radius: 40px;
    box-shadow: 0 0 30px rgba(0,0,0,0.7);
    z-index: -9999;
    pointer-events: none;
  }

  /* Mantener el fondo leopardo fijo aunque bajes */
  body {
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* Todos los contenedores transparentes */
  #__next, #root, .App, .AppContainer, [data-test-id="app-root"],
  div[role="main"], main, section, .tBJ, .zI7, .hCL, .Jea, .X8D {
    background: transparent !important;
  }

  /* Cabecera y buscador en tono canela semi-transparente */
  header, .Header, .topNav, [data-test-id="header"] {
    background: rgba(26, 18, 11, 0.85) !important; /* marrón oscuro con transparencia */
    backdrop-filter: blur(6px);
    border-bottom: 1px solid #3d2b1f;
  }

  /* Buscador más visible y elegante */
  input[type="search"], .SearchBox, .searchBox {
    background: rgba(0,0,0,0.6) !important;
    color: #f8e8c6 !important;
    border-radius: 20px !important;
    border: 1px solid #3d2b1f !important;
    padding: 6px 14px !important;
  }
  input[type="search"]::placeholder { color: #d8b88a !important; }

  /* Textos en dorado suave y legibles */
  header *, .Header *, .topNav *, .SearchBox *, .Pin *, .gridItem * {
    color: #f2e2c4 !important;
    fill: #f2e2c4 !important;
  }

  /* Cambiar el logo de Pinterest por un tono canela/leopardo */
  [data-test-id="header-logo"] svg path {
    fill: #c28f4b !important; /* tono marrón dorado */
  }

  /* Pines y textos sin fondos negros */
  .Pin, .Board, .gridItem, .searchResult, .MIw, .tBJ {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Corregir el color de texto bajo los pines */
  .Pin .tBJ, .Pin .zI7, .Pin .XiG, .Pin .hCL {
    color: #f9e9c6 !important;
  }

  /* Iconos laterales (inicio, notificaciones, mensajes...) */
  nav, .Hn_ {
    background: rgba(0,0,0,0.7) !important;
  }
  nav svg path {
    fill: #f2e2c4 !important;
    transition: 0.3s;
  }
  nav svg:hover path {
    fill: #c28f4b !important; /* canela al pasar el ratón */
  }

  /* Scrollbar personalizada */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: #3d2b1f;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #c28f4b;
  }
}
